using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PerpetualClockOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/PerpetualClockOmenData")]
public class PerpetualClockOmenData : EndOfTurnGainSomethingPerDiceOmen
{
	private Action perpetualClockOmenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		base.Initialize(omenInstance);
		perpetualClockOmenAction = delegate
		{
		};
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.PerpetualClockOmenAction = perpetualClockOmenAction;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.PerpetualClockOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		return base.localizationManager.GetLocalizedString("GoddessTrickery_D") + "\n" + GetOmenRawLocalizedDescription() + "\n" + base.OmenConvertedDescription() + "\n" + base.localizationManager.GetLocalizedCorruptionNotIncreasedByCorruptionModifier();
	}
}
